import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 collectAmount, uint256 lockTime, uint256 senderSeed, uint256 changeVal) public {
        // Bound minSum to reasonable non-zero value, ensure collectAmount <= minSum to pass balance check
        vm.assume(minSum > 0 && minSum < type(uint256).max / 2);
        vm.assume(collectAmount <= minSum);
        // Prevent lockTime overflow in Put
        vm.assume(lockTime < type(uint256).max - block.timestamp);
        // Ensure senderSeed generates distinct address, avoid burn/zero
        vm.assume(senderSeed != 0 && senderSeed != address(uint160(this)) && senderSeed != uint160(address(c)));
        address sender = address(uint160(senderSeed));
        // Ensure changeVal is different from minSum so potential mutation is detectable
        vm.assume(changeVal != minSum);

        // Setup: initialize Log contract
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        // Set MinSum before initialization
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund sender with enough ether to Put and cover collect gas
        vm.deal(sender, 1 ether);
        // Warp to a safe starting time
        vm.warp(1000);

        // Put enough balance to satisfy MinSum and unlock
        vm.prank(sender);
        c.Put{value: minSum}(lockTime);
        // Warp past unlock time so Collect succeeds
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before the call
        uint256 minSumBefore = c.MinSum();

        // Try to change MinSum after initialization via the buggy method; this is allowed in bug, not in reference
        // We simulate a prank call to SetMinSum to see if it mutates
        vm.prank(address(uint160(changeVal % (type(uint128).max - 1) + 1)));
        try c.SetMinSum(changeVal) {} catch {}

        // Perform Collect (should succeed in both ref and bug)
        vm.prank(sender);
        try c.Collect(collectAmount) {} catch {}

        uint256 minSumAfter = c.MinSum();

        // Rule: MinSum must be unchanged from its pre-initialization value.
        // In reference, SetMinSum after initialization reverts; in mutant it succeeds, so minSumAfter may differ.
        assertTrue(minSumAfter == minSumBefore);
    }
}

