    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt, uint256 lockTime, uint256 setVal) public {
        // amt: Collect amount, lockTime: Put lock time, setVal: attempted new MinSum
        vm.assume(amt > 0 && amt < type(uint256).max / 2);
        vm.assume(lockTime < type(uint256).max / 2);
