pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract
        c.Initialized();
    }

    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 depositAmt, uint256 collectAmt, address attacker) public {
        // Bound parameters to reasonable ranges
        minSum = bound(minSum, 1, type(uint128).max);
        depositAmt = bound(depositAmt, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);
        lockTime = bound(lockTime, 0, 365 days);

        // Ensure attacker is not the test contract itself and has no code (EOA)
        vm.assume(attacker != address(this));
        vm.assume(attacker.code.length == 0);

        // Set initial MinSum
        vm.prank(address(this));
        c.SetMinSum(minSum);

        // Deploy re-entrant attacker helper
        ReEntrantAttacker helper = new ReEntrantAttacker(c, minSum);

        // Fund attacker and helper
        vm.deal(attacker, 100 ether);
        vm.deal(address(helper), 0);

        // Attacker deposits into C via fallback (Put(0)) and gets an account
        vm.prank(attacker);
        (bool s,) = address(c).call{value: depositAmt}("");
        require(s, "deposit failed");

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1 days);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attacker triggers Collect which re-enters via helper to change MinSum
        vm.prank(attacker);
        try c.Collect(collectAmt) {
            // Collect succeeded (if conditions met)
        } catch {
            // Collect reverted (insufficient balance, unlock time, etc.)
        }

        uint256 minSumAfter = c.MinSum();

        // If Collect did not revert, MinSum must remain unchanged
        // Since the re-entrant call in Collect can only execute if Collect succeeds,
        // the assertion captures: after any non-reverting Collect, MinSum must equal its prior value.
        // The bug allows SetMinSum to change it, violating this property.
        // We check that if the call did not revert (we cannot directly know, but the helper
        // only acts on success), then minSumAfter == minSumBefore.
        // We assert a general rule: the difference should be zero if the helper didn't change it.
        // But the helper *always* attempts to change it inside the callback if Collect succeeds.
        // So we assert that after the transaction, MinSum is unchanged.
        assertEq(minSumAfter, minSumBefore);
    }
}

contract ReEntrantAttacker {
    C target;
    uint256 newMinSum;

    constructor(C _target, uint256 _newMinSum) {
        target = _target;
        newMinSum = _newMinSum;
    }

    fallback() external payable {
        // Re-entrant call: change MinSum via SetMinSum
        target.SetMinSum(newMinSum);
    }

    receive() external payable {
        target.SetMinSum(newMinSum);
    }
}

