contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool _initBefore) public {
        require(true);
        if (_initBefore) {
            try c.Initialized() {} catch {}
        }
        bool reverted; try c.SetLogFile(address(0)) { reverted = false; } catch { reverted = true; }
        // SetLogFile should revert exactly when the contract has been initialized (Initialized has been called),
        // i.e., initialized == true. The mutant inverts this condition.
        bool initGetter;
        // There is no public getter for 'intitalized', but it's reachable via Initialized public function.
        // We deduce initialization state by checking whether calling SetMinSum succeeds:
        // SetMinSum also uses the `if(intitalized)revert()` guard, so it reverts iff initialized==true.
        bool setMinReverted; try c.SetMinSum(0) { setMinReverted = false; } catch { setMinReverted = true; }
        // On original P: reverted == setMinReverted (both revert only when initialized)
        // On mutant M: SetLogFile reverts when !initialized, so reverted != setMinReverted when initialized is false;
        // they match only when initialized is true (both revert). General inequality covering all states:
        // If initialized is false, original reverts neither; mutant reverts SetLogFile only.
        // If initialized is true, original reverts both; mutant reverts SetMinSum only.
        // Therefore, on P: reverted == setMinReverted always. On M: reverted != setMinReverted always.
        assert(reverted == setMinReverted);
    }
}

