pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n, uint64 putValue) public {
        // n: number of Put calls (>0); putValue: base value in wei for each Put call
        vm.assume(n > 0 && n <= 255);
        vm.assume(putValue > 0);

        address actor = makeAddr("actor");
        vm.deal(actor, type(uint256).max);
        vm.prank(actor);

        uint totalSent = 0;
        for (uint i = 0; i < n; i++) {
            uint v = putValue + i; // slightly varying amounts to explore edge cases
            totalSent += v;
            vm.prank(actor);
            c.Put{value: v}(0);
        }

        (uint unlockTime, uint accBalance) = c.Acc(actor);
        unlockTime;
        // Assert: recorded account balance equals total Ether sent by actor
        assertEq(accBalance, totalSent);
    }
}

