pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 nPuts, uint64 putAmount) public {
        // Bound number of puts to a reasonable range
        vm.assume(nPuts > 0 && nPuts <= 100);
        vm.assume(putAmount > 0);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);

        address user = address(0x1234);
        vm.deal(user, uint256(putAmount) * nPuts);
        vm.startPrank(user);

        // Perform nPuts
        for (uint8 i = 0; i < nPuts; i++) {
            c.Put{value: putAmount}(0);
        }
        vm.stopPrank();

        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        // Now collect all funds
        uint256 totalBalance = 0;
        // We need to collect from user, but the mutant adds 1 wei per put to Acc[user].balance
        uint256 userBalance = c.Acc(user).balance;
        if (userBalance > 0) {
            vm.prank(user);
            c.Collect(userBalance);
        }

        // After collection, assert that the contract Ether balance is zero only if all Acc balances are zero
        // The general rule: Sum of all Acc balances <= address(c).balance
        // This holds for reference because Acc balances mirror ether received; mutant adds extra 1 wei per Put
        uint256 sumAccBalances = c.Acc(user).balance;
        assertTrue(sumAccBalances <= address(c).balance);
    }
}

