pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint8 putCalls, uint256 lockTime, uint256 collectAmount) public {
        vm.assume(putCalls >= 1);
        vm.assume(lockTime < type(uint256).max);
        address user = address(0x1000);
        vm.deal(user, type(uint256).max);
        vm.startPrank(user);
        c.Initialized();
        c.SetMinSum(minSum);
        uint256 totalSent = 0;
        for (uint8 i = 0; i < putCalls; i++) {
            uint256 val = 1;
            c.Put{value: val}(lockTime);
            totalSent += val;
        }
        uint256 contractBalanceBefore = address(c).balance;
        vm.assume(collectAmount <= c.Acc(user));
        vm.assume(countCollectable() > 0);
        vm.warp(block.timestamp + lockTime + 1);
        c.Collect(collectAmount);
        uint256 contractBalanceAfter = address(c).balance;
        uint256 accBalance = c.Acc(user);
        vm.stopPrank();
        assertTrue(accBalance <= contractBalanceAfter + putCalls);
    }

    function countCollectable() internal view returns (uint256) {
        address user = address(0x1000);
        (uint256 unlockTime, uint256 balance) = c.Acc(user);
        if (block.timestamp > unlockTime && balance >= c.MinSum()) {
            return balance;
        }
        return 0;
    }
}

